contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: make one play that does NOT trigger a win (random==1) and then check pot increased exactly by the ticket amount.
    // We cannot control randomness, so we model the sequence with two plays: first a play that we require did NOT reset the pot (i.e. pot > 0 afterwards),
    // then make a second play and assert pot increased by exactly the sent ticket amount when no reset occurred.

    function run(uint amount) public payable {
        // Preconditions for meaningful test: caller must send exactly 'amount' to c in each call below
        require(amount > 0);
        require(address(this).balance >= amount * 2);

        // read initial pot
        uint pot0 = c.pot();

        // first play: send amount
        c.play{value: amount}();

        // observe pot after first play
        uint pot1 = c.pot();

        // Require that the first play did NOT reset the pot (i.e., no payout happened). This ensures pot1 >= pot0 + amount.
        require(pot1 >= pot0 + amount);

        // second play: send same amount
        c.play{value: amount}();

        // observe pot after second play
        uint pot2 = c.pot();

        // On the original contract P (which requires exact ticket amount), if neither play triggered a reset then each play
        // that didn't reset increases the pot by exactly the sent ticket amount. Therefore pot2 == pot1 + amount.
        // The mutant M that allows smaller payments can accept partial payments and thus pot may increase by less than amount,
        // violating this assertion when we send 'amount' but the contract accepted something different internally.
        assert(pot2 == pot1 + amount);
    }

    // Allow funding this test contract so it can forward ETH to c
    receive() external payable {}
}

